// hooks/useLiveKitRoom.ts — corrected connect effect
import { Room, RoomEvent } from 'livekit-client';
import { useEffect, useRef, useCallback } from 'react';

export function useLiveKitRoom(roomName: string, onError?: (e: Error) => void) {
  const roomRef = useRef<Room | null>(null);
  const isConnectingRef = useRef(false);

  if (!roomRef.current) {
    roomRef.current = new Room({ adaptiveStream: true, dynacast: true });
  }
  const room = roomRef.current;

  useEffect(() => {
    if (!roomName) return;
    if (isConnectingRef.current) return;

    let aborted = false;
    isConnectingRef.current = true;

    async function connect() {
      try {
        const res = await fetch(`/api/calls/token/${roomName}`);
        if (!res.ok) throw new Error(`Token fetch failed: ${res.status}`);
        const { token, liveKitUrl } = await res.json();

        if (aborted) return; // StrictMode already cleaned up

        await room.connect(liveKitUrl, token);

        if (aborted) {
          room.disconnect();
          return;
        }
      } catch (e) {
        if (!aborted) onError?.(e as Error);
      } finally {
        isConnectingRef.current = false;
      }
    }

    connect();

    return () => {
      aborted = true;
      room.disconnect();
    };
  }, [roomName]); // roomName only — room and onError must NOT be in deps

  return { room };
}

