// Condensed SocketProvider pattern
import Ably from 'ably';
import { createContext, useContext, useEffect, useRef, ReactNode } from 'react';
import { useSession } from 'next-auth/react';

type Handler = (data: unknown) => void;

interface SocketContextValue {
  on: (event: string, handler: Handler) => void;
  off: (event: string, handler: Handler) => void;
  isConnected: boolean;
}

const SocketContext = createContext<SocketContextValue | null>(null);

export function SocketProvider({ children }: { children: ReactNode }) {
  const { data: session } = useSession();
  const realtimeRef = useRef<Ably.Realtime | null>(null);
  const listenersRef = useRef<Map<string, Set<Handler>>>(new Map());
  const isConnectedRef = useRef(false);

  useEffect(() => {
    if (!session?.user?.id) return;

    const realtime = new Ably.Realtime({ authUrl: '/api/auth/ably-token' });
    realtimeRef.current = realtime;

    const userChannel = realtime.channels.get(`user:${session.user.id}`);
    const stressChannel = realtime.channels.get('stress:alerts');

    const dispatch = (event: string) => (msg: Ably.Types.Message) => {
      listenersRef.current.get(event)?.forEach(h => h(msg.data));
    };

    // Subscribe ONCE per event on the Ably channel
    const events = ['text_message_received','voice_message_received','call_incoming','call_declined','call_ended','call_missed','friend_request_received','friend_request_accepted','nearby_driver_update','error'];
    events.forEach(e => userChannel.subscribe(e, dispatch(e)));
    stressChannel.subscribe('stress_signal_alert', dispatch('stress_signal_alert'));

    realtime.connection.on('connected', () => { isConnectedRef.current = true; });
    realtime.connection.on('disconnected', () => { isConnectedRef.current = false; });

    return () => {
      userChannel.unsubscribe();
      stressChannel.unsubscribe();
      realtime.close();
      realtimeRef.current = null;
      listenersRef.current.clear();
    };
  }, [session?.user?.id]);

  const on = (event: string, handler: Handler) => {
    if (!listenersRef.current.has(event)) listenersRef.current.set(event, new Set());
    listenersRef.current.get(event)!.add(handler);
  };

  const off = (event: string, handler: Handler) => {
    listenersRef.current.get(event)?.delete(handler);
  };

  return (
    <SocketContext.Provider value={{ on, off, isConnected: isConnectedRef.current }}>
      {children}
    </SocketContext.Provider>
  );
}

export function useSocket() {
  const ctx = useContext(SocketContext);
  if (!ctx) throw new Error('useSocket must be used within SocketProvider');
  return ctx;
}
